Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/amdgpu: Make sure IB tests flushed after IP resume
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Fixes: 2c773de2 (drm/amdgpu: defer test IBs on the rings at boot (V3))

Signed-off-by: Leo Liu <leo.liu@amd.com>
Reviewed-by: Christian König <christian.koenig@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug was caused by the failure to flush the Instruction Buffer (IB) tests after the IP resume process, which could lead to stale or unprocessed commands remaining in the buffer, potentially causing instability or incorrect behavior in the graphics processing unit (GPU) operations.

Here is the patch:
  */
 int amdgpu_device_resume(struct drm_device *dev, bool resume, bool fbcon)
 {
 	struct drm_connector *connector;
 	struct amdgpu_device *adev = dev->dev_private;
 	struct drm_crtc *crtc;
 	int r = 0;

 	if (dev->switch_power_state == DRM_SWITCH_POWER_OFF)
 		return 0;

 	if (fbcon)
 		console_lock();

 	if (resume) {
 		pci_set_power_state(dev->pdev, PCI_D0);
 		pci_restore_state(dev->pdev);
 		r = pci_enable_device(dev->pdev);
 		if (r)
 			goto unlock;
 	}

 	/* post card */
 	if (amdgpu_device_need_post(adev)) {
 		r = amdgpu_atom_asic_init(adev->mode_info.atom_context);
 		if (r)
 			DRM_ERROR("amdgpu asic init failed\n");
 	}

 	r = amdgpu_device_ip_resume(adev);
 	if (r) {
 		DRM_ERROR("amdgpu_device_ip_resume failed (%d).\n", r);
 		goto unlock;
 	}
 	amdgpu_fence_driver_resume(adev);


 	r = amdgpu_device_ip_late_init(adev);
 	if (r)
 		goto unlock;

 	/* pin cursors */
 	list_for_each_entry(crtc, &dev->mode_config.crtc_list, head) {
 		struct amdgpu_crtc *amdgpu_crtc = to_amdgpu_crtc(crtc);

 		if (amdgpu_crtc->cursor_bo) {
 			struct amdgpu_bo *aobj = gem_to_amdgpu_bo(amdgpu_crtc->cursor_bo);
 			r = amdgpu_bo_reserve(aobj, true);
 			if (r == 0) {
 				r = amdgpu_bo_pin(aobj,
 						  AMDGPU_GEM_DOMAIN_VRAM,
 						  &amdgpu_crtc->cursor_addr);
 				if (r != 0)
 					DRM_ERROR("Failed to pin cursor BO (%d)\n", r);
 				amdgpu_bo_unreserve(aobj);
 			}
 		}
 	}
 	r = amdgpu_amdkfd_resume(adev);
 	if (r)
 		return r;

+	/* Make sure IB tests flushed */
+	flush_delayed_work(&adev->late_init_work);
+
 	/* blat the mode back in */
 	if (fbcon) {
 		if (!amdgpu_device_has_dc_support(adev)) {
 			/* pre DCE11 */
 			drm_helper_resume_force_mode(dev);

 			/* turn on display hw */
 			drm_modeset_lock_all(dev);
 			list_for_each_entry(connector, &dev->mode_config.connector_list, head) {
 				drm_helper_connector_dpms(connector, DRM_MODE_DPMS_ON);
 			}
 			drm_modeset_unlock_all(dev);
 		}
 	}

 	drm_kms_helper_poll_enable(dev);

 	/*
 	 * Most of the connector probing functions try to acquire runtime pm
 	 * refs to ensure that the GPU is powered on when connector polling is
 	 * performed. Since we're calling this from a runtime PM callback,
 	 * trying to acquire rpm refs will cause us to deadlock.
 	 *
 	 * Since we're guaranteed to be holding the rpm lock, it's safe to
 	 * temporarily disable the rpm helpers so this doesn't deadlock us.
 	 */
 #ifdef CONFIG_PM
 	dev->dev->power.disable_depth++;
 #endif
 	if (!amdgpu_device_has_dc_support(adev))
 		drm_helper_hpd_irq_event(dev);
 	else
 		drm_kms_helper_hotplug_event(dev);
 #ifdef CONFIG_PM
 	dev->dev->power.disable_depth--;
 #endif

 	if (fbcon)
 		amdgpu_fbdev_set_suspend(adev, 0);

 unlock:
 	if (fbcon)
 		console_unlock();

 	return r;
 }



